from pathlib import Path
import json,hashlib,collections,datetime
r=Path(__import__('sys').argv[1]);review=r/'analysis/review'
def descriptor(p):return {'path':str(p),'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
receipts=[];counts=collections.Counter();objective=collections.defaultdict(collections.Counter)
def walk(o,path=''):
 if isinstance(o,dict):
  if 'verdict' in o:counts[o['verdict']]+=1;objective[path.split('.')[-1]][o['verdict']]+=1
  for k,v in o.items():walk(v,path+'.'+k)
 elif isinstance(o,list):
  for v in o:walk(v,path)
for name in ['blind-a.json','blind-b.json','blind-c.json']:
 p=review/name;d=json.loads(p.read_text());walk(d);receipts.append(descriptor(p))
inputs=set()
for n in [1,2]:
 p=review/f'request-{n}.json';receipts.append(descriptor(p));request=json.loads(p.read_text())
 for s in request['sequences']:
  inputs.update(Path(v) for v in s['faceSheets'].values())
  inputs.update(Path(x['path']) for x in s['crops'])
seal={'schema':'csx-nr-regional-blind-seal-v1','sealedUtc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'reviewsAndRequests':receipts,'anonymousInputs':[descriptor(p) for p in sorted(inputs)],'mappingRevealedToReviewers':False,'verdictCounts':dict(counts),'objectiveKeyCounts':{k:dict(v) for k,v in objective.items()},'scope':'Regional exploratory review; complete 12-frame face crops per eye and explicitly recorded material-crop coverage. Not full-frame or frame-rate qualification.'}
p=r/'analysis/sealed-reviews.json'
with p.open('x') as f:json.dump(seal,f,indent=2)
print(json.dumps({'seal':descriptor(p),'verdictCounts':dict(counts),'objectives':seal['objectiveKeyCounts'],'anonymousInputs':len(inputs)},indent=2))

